const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=value=>{try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:'';}catch{return '';}};
const urlLink=(url,label,css='')=>safeURL(url)?`<a class="${css}" href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${label}</a>`:'';
let lang=(['en','es','ca'].includes(new URLSearchParams(location.search).get('lang'))?new URLSearchParams(location.search).get('lang'):'en'),data,filter=(['note','conference','activity','blog'].includes(new URLSearchParams(location.search).get('filter'))?new URLSearchParams(location.search).get('filter'):'all'),expanded=false;
const textFor=(entry,key)=>key==='title'&&entry.type==='paper'&&entry.scientific_title?.trim()?entry.scientific_title.trim():entry[key]?.[lang]||entry[key]?.en||entry[key]?.es||'';
const isNewsArchive=()=>location.pathname.endsWith('/section.html')&&new URLSearchParams(location.search).get('view')==='noticias';
const allNewsLabel=()=>({en:'View all news',es:'Ver todas las noticias',ca:'Veure totes les notícies'}[lang]);
const order=(a,b)=>b.date.localeCompare(a.date);
const entryURL=entry=>'entry.html?id='+encodeURIComponent(entry.id)+'&lang='+lang;
const homeURL=()=> 'index.html?lang='+lang;
const sectionURL=id=>id==='investigacion'?homeURL()+'#about':id==='software'?'software.html?lang='+lang:'section.html?view='+encodeURIComponent(['blog','actividades'].includes(id)?'noticias':id)+'&lang='+lang;
let softwareFilter='all';
function publicationDate(entry){return new Intl.DateTimeFormat({en:'en-GB',es:'es-ES',ca:'ca-ES'}[lang],{...(entry.date_precision==='year'?{}:{month:'short'}),year:'numeric'}).format(new Date(entry.date+'T12:00:00'));}
function dateFor(entry){const precision=entry.date_precision||'day';return new Intl.DateTimeFormat({es:'es-ES',ca:'ca-ES',en:'en-GB'}[lang],{year:'numeric',...(precision!=='year'?{month:'short'}:{}),...(precision==='day'?{day:'numeric'}:{})}).format(new Date(entry.date+'T12:00:00'));}
function links(entry){const t=dictionaries[lang],doi=entry.doi?'https://doi.org/'+entry.doi.replace(/^https?:\/\/doi.org\//,''):'';return `<div class="rowlinks">${entry.url&&entry.url!==doi?urlLink(entry.url,t.resource):''}${doi?urlLink(doi,'DOI'):''}${entry.social?urlLink(entry.social,t.social):''}</div>`;}
function reference(entry,full=false){let authors=entry.authors||'';const parts=authors.split(';');if(!full&&parts.length>3)authors=parts.slice(0,3).join(';')+' et al.';return authors||entry.venue?`<p class="reference">${esc(authors)}${entry.venue?` · <i>${esc(entry.venue)}</i>`:''}${entry.paper_status?` · ${esc(dictionaries[lang].status[entry.paper_status]||'')}`:''}</p>`:'';}
function imageFor(entry){return entry.image&&(/^\/uploads\/[a-zA-Z0-9_\-./%]+$/.test(entry.image)||safeURL(entry.image))?`<img class="entry-image" src="${esc(entry.image)}" alt="${esc(entry.image_alt?.[lang]||entry.image_alt?.es||'')}">`:'';}
function summaryFor(entry){const plain=(entry.summary?.[lang]||textFor(entry,'body').split('\n')[0]).replace(/[*_`#]/g,'');return plain.length>190?plain.slice(0,187)+'…':plain;}
function entryCard(entry){return `<article class="paper"><p class="sub">${dateFor(entry)}${entry.external_blog?' · '+dictionaries[lang].ctfcBlog:''}</p><h3><a class="entry-title" href="${entryURL(entry)}" data-entry="${esc(entry.id)}">${esc(textFor(entry,'title'))}</a></h3><p>${esc(summaryFor(entry))}</p>${reference(entry)}${links(entry)}</article>`;}
function newsThumbnail(entry){const src=entry.thumbnail||entry.image||'/uploads/news/landscape.svg';return /^\/uploads\/[a-zA-Z0-9_\-./%]+$/.test(src)||safeURL(src)?src:'/uploads/news/landscape.svg';}
function newsFilters(){const entries=data.entries.filter(e=>!e.bibliographic&&['conference','note','activity','blog'].includes(e.type));const categories=['all',...['paper','conference','note','activity','blog'].filter(type=>entries.some(e=>e.type===type))];const labels=lang==='ca'?{all:'Tot',paper:'Articles',conference:'Congressos',note:'Notícies',activity:'Activitats',blog:'Divulgació'}:lang==='es'?{all:'Todo',paper:'Artículos',conference:'Congresos',note:'Noticias',activity:'Actividades',blog:'Divulgación'}:{all:'All',paper:'Papers',conference:'Conferences',note:'News',activity:'Activities',blog:'Outreach'};return categories.map(type=>`<button data-filter="${type}" aria-pressed="${filter===type}">${labels[type]} <span class="filter-count">${type==='all'?entries.length:entries.filter(e=>e.type===type).length}</span></button>`).join('');}
function newsPublication(entry){
 if(entry.type!=='paper')return '';
 const labels={en:{published:'Published',accepted:'Accepted',preprint:'Preprint',in:'in'},es:{published:'Publicado',accepted:'Aceptado',preprint:'Preprint',in:'en'},ca:{published:'Publicat',accepted:'Acceptat',preprint:'Preprint',in:'a'}}[lang];
 const status=labels[entry.paper_status]||'';
 if(!status&&!entry.venue)return '';
 const join=entry.venue&&['published','accepted'].includes(entry.paper_status)?' '+labels.in+' ':entry.venue&&status?' · ':'';
 return `<p class="news-publication">${esc(status)}${join}${entry.venue?`<i>${esc(entry.venue)}</i>`:''}</p>`;
}
function renderNews(){const t=dictionaries[lang],list=data.entries.filter(e=>!e.bibliographic&&['conference','note','activity','blog'].includes(e.type)&&(filter==='all'||e.type===filter)).sort(order),shown=isNewsArchive()?list:list.slice(0,3);document.getElementById('news').innerHTML=shown.map(e=>`<article class="news-item" role="listitem"><a class="news-thumbnail ${e.type==='paper'?'paper-figure':''}" href="${entryURL(e)}" tabindex="-1" aria-hidden="true"><img src="${esc(newsThumbnail(e))}" width="480" height="260" alt="" title="${esc(textFor(e,'thumbnail_credit'))}" loading="lazy"></a><div class="news-copy"><p class="news-meta"><time datetime="${e.date}">${dateFor(e)}</time><span class="tag ${e.type}">${t.types[e.type]}</span></p><h2><a class="entry-title" href="${entryURL(e)}">${esc(textFor(e,'title'))}</a></h2>${newsPublication(e)}<p class="news-summary">${esc(summaryFor(e))}</p><a class="news-read-more" href="${entryURL(e)}" aria-label="${esc(t.read+': '+textFor(e,'title'))}">${t.read} <span aria-hidden="true">→</span></a></div></article>`).join('');document.getElementById('news-empty').hidden=!!list.length;document.getElementById('count').textContent=t.count(shown.length,list.length);document.getElementById('count').hidden=!isNewsArchive();const b=document.getElementById('expand');b.hidden=true;b.textContent=expanded?t.less:t.previous;b.setAttribute('aria-expanded',String(expanded));}
function siteFooter(){
 const t=dictionaries[lang],copy={en:{what:'What we do',contact:'Contact',about:'A research group at',work:['Model forest and landscape dynamics under global change.','Explore management and restoration scenarios to support decisions.','Share tools, research and learning through software, publications and events.'],profile:'Group enquiries · Núria Aquilué',institution:'Contact CTFC',affiliation:'Forest Science and Technology Centre of Catalonia'},es:{what:'Qué hacemos',contact:'Contacto',about:'Un grupo de investigación del',work:['Modelizamos la dinámica de bosques y paisajes ante el cambio global.','Exploramos escenarios de gestión y restauración para apoyar decisiones.','Compartimos herramientas, investigación y formación mediante software, publicaciones y encuentros.'],profile:'Consultas del grupo · Núria Aquilué',institution:'Contactar con el CTFC',affiliation:'Centro de Ciencia y Tecnología Forestal de Cataluña'},ca:{what:'Què fem',contact:'Contacte',about:'Un grup de recerca del',work:['Modelitzem la dinàmica de boscos i paisatges davant del canvi global.','Explorem escenaris de gestió i restauració per donar suport a les decisions.','Compartim eines, recerca i formació mitjançant software, publicacions i trobades.'],profile:'Consultes del grup · Núria Aquilué',institution:'Contactar amb el CTFC',affiliation:'Centre de Ciència i Tecnologia Forestal de Catalunya'}}[lang];
 return `<footer class="footer institutional-footer"><div class="footer-grid"><div class="footer-identity"><a class="footer-brand" href="${homeURL()}">LANDMOD<span>.</span></a><p>${t.footer}</p><p class="footer-affiliation">${copy.about}</p><a class="ctfc-identity" href="https://www.ctfc.cat/" target="_blank" rel="noopener noreferrer"><img src="/uploads/identity/ctfc.png" width="704" height="194" alt="CTFC"><span>${copy.affiliation}</span></a></div><section><h2>${copy.what}</h2><ul>${copy.work.map(item=>`<li>${item}</li>`).join('')}</ul></section><section><h2>${copy.contact}</h2><address>Ctra. de Sant Llorenç de Morunys, km 2<br>25280 Solsona · Lleida</address><p>${urlLink('https://www.ctfc.cat/personal24_det.php?id=60',copy.profile)}</p><p>${urlLink('https://www.ctfc.cat/contacte.php',copy.institution)}</p></section></div><div class="footer-bottom"><span>LANDMOD · CTFC</span><a href="admin/">${t.edit}</a></div></footer>`;
}
function personCard(person){
 const icon=(type)=>type==='email'?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/></svg>':type==='linkedin'?'<svg viewBox="0 0 24 24" fill="currentColor"><rect x="3" y="9" width="4" height="12"/><circle cx="5" cy="5" r="2"/><path d="M10 9h4v1.6c1-1.4 2.3-1.9 3.6-1.9 3.5 0 3.9 2.5 3.9 5.6V21h-4v-6c0-1.6-.1-3-1.8-3s-1.8 1.5-1.8 3v6H10z"/></svg>':type==='orcid'?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="12" cy="12" r="10"/><path d="M7 10v7m4-7v7h2a3.5 3.5 0 0 0 0-7z"/><circle cx="7" cy="7" r=".7" fill="currentColor"/></svg>':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M14 3h7v7m0-7L10 14M10 5H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-5"/></svg>';
 const labels={en:{email:'Email',profile:'Institutional profile'},es:{email:'Correo electrónico',profile:'Perfil institucional'},ca:{email:'Correu electrònic',profile:'Perfil institucional'}}[lang];
 const contact=(type,url,label)=>`<a href="${esc(url)}" class="person-contact" aria-label="${esc(label+' · '+person.name)}" title="${esc(label)}" ${type==='email'?'':'target="_blank" rel="noopener noreferrer"'}>${icon(type)}</a>`;
 const email=/^[a-zA-Z0-9._%+-]+@[a-zA-Z0-9.-]+\.[a-z]{2,}$/.test(person.email||'')?contact('email','mailto:'+person.email,labels.email):'';
 return `<article class="person"><a class="person-photo" href="${esc(safeURL(person.profile))}" target="_blank" rel="noopener noreferrer"><img src="${esc(person.image)}" width="110" height="110" alt="${esc(person.name)}" loading="lazy"></a><div class="person-info"><h3>${urlLink(person.profile,esc(person.name))}</h3><p class="person-role">${esc(person['role_'+lang]||person.role_en)}</p><p class="person-expertise">${esc(person['expertise_'+lang]||person.expertise_en||'')}</p><div class="person-contacts">${email}${safeURL(person.linkedin)?contact('linkedin',safeURL(person.linkedin),'LinkedIn'):''}${safeURL(person.orcid)?contact('orcid',safeURL(person.orcid),'ORCID'):''}${contact('profile',safeURL(person.profile),labels.profile)}</div></div></article>`;
}
function render(){const t=dictionaries[lang];document.documentElement.lang=lang;document.title=`LANDMOD · ${t.footer} · CTFC`;document.querySelector('meta[name="description"]').content=t.intro;
const ids=['noticias','publicaciones','projects','software','equipo'];const papers=data.entries.filter(e=>e.type==='paper').sort(order),blogs=data.entries.filter(e=>e.type==='blog').sort(order);
document.getElementById('app').innerHTML=`<header><div class="bar"><a class="brand" href="${homeURL()}#inicio" aria-label="LANDMOD · CTFC">LANDMOD<span>.</span></a><nav aria-label="${lang==='ca'?"Navegació principal":lang==='es'?'Navegación principal':'Main navigation'}">${ids.map((id,i)=>`<a href="${sectionURL(id)}">${t.nav[i]}</a>`).join('')}</nav><div class="languages" aria-label="Language"><button data-lang="ca" aria-pressed="${lang==='ca'}">CA</button><span>/</span><button data-lang="es" aria-pressed="${lang==='es'}">ES</button><span>/</span><button data-lang="en" aria-pressed="${lang==='en'}">EN</button></div></div></header>
<main id="inicio"><section class="intro"><div><div class="eyebrow">${t.eyebrow}</div><h1>${t.heading}</h1><p>${t.intro}</p><div class="intro-links"><a href="#investigacion">${t.introLink}</a>${urlLink(official,t.official)}</div></div><figure class="hero-visual"><img src="/uploads/landmod-landscape.jpg" width="866" height="280" alt="${lang==='ca'?"Visualització d’un relleu amb boscos i corbes de nivell":lang==='es'?'Visualización de un relieve con bosques y curvas de nivel':'Visualisation of terrain with forests and contour lines'}"><figcaption>${t.imageCaption}</figcaption></figure></section>
<section class="section" id="noticias"><div class="section-head"><div><h2>${t.news}</h2><p>${t.newsSub}</p></div><a href="${sectionURL('actividades')}">${t.activities}</a></div><div class="filters" role="group" aria-label="${t.news}">${newsFilters()}</div><div id="news" class="news-list" role="list" aria-label="${t.news}"></div><p id="news-empty" class="sub">${t.empty}</p><button class="more" id="expand" aria-expanded="${expanded}"></button><p id="count" class="count" aria-live="polite"></p><div class="news-archive-link"><a href="section.html?view=noticias&lang=${lang}">${allNewsLabel()} <span aria-hidden="true">→</span></a></div></section>
<section class="section" id="investigacion"><div class="section-head"><div><h2>${t.research}</h2><p>${t.researchSub}</p></div>${urlLink(official,t.official)}</div><div class="research">${t.researchAreas.map(([title,body])=>`<article><h3>${title}</h3><p>${body}</p></article>`).join('')}</div><h3>${t.projects}</h3><p class="sub">${t.projectsSub}</p><div class="project-grid">${data.projects.map(p=>`<article class="project"><span class="category">${esc(p['category_'+lang])}</span><h3>${urlLink(p.url,esc(p.name))}</h3><p>${esc(p['label_'+lang])}</p></article>`).join('')}</div></section>
<section class="section" id="software"><div class="section-head"><div><h2>Software</h2><p>${lang==='ca'?"Eines per explorar, simular i planificar.":lang==='es'?'Herramientas para explorar, simular y planificar.':'Tools to explore, simulate and plan.'}</p></div><a href="software.html?lang=${lang}">${lang==='ca'?"Explorar el software":lang==='es'?'Explorar el software':'Explore the software'}</a></div><div class="software-teasers">${(data.software||[]).map(tool=>`<a href="software.html?lang=${lang}#${esc(tool.id)}"><span class="tool-symbol">${tool.kind==='r'?'R':'WEB'}</span><span><strong>${esc(tool.name)}</strong><small>${lang==='ca'?(tool.kind==='r'?'Paquet R':'Aplicació web'):lang==='es'?(tool.kind==='r'?'Paquete R':'Aplicación web'):(tool.kind==='r'?'R package':'Web application')}</small></span></a>`).join('')}</div></section>
<div class="section split"><section id="publicaciones" class="section-target"><h2>${t.papers}</h2><p class="sub">${t.papersSub}</p>${papers.slice(0,3).map(entryCard).join('')||`<p class="empty-state">${t.empty}</p>`}${papers.length>3?`<details class="all-papers"><summary>${t.allPapers} (${papers.length})</summary>${papers.slice(3).map(entryCard).join('')}</details>`:''}</section><section id="actividades" class="section-target"><h2>${t.activities}</h2><p class="sub">${t.activitiesSub}</p><div id="events"></div></section></div>
<section class="section" id="equipo"><div class="section-head"><div><h2>${t.team}</h2><p>${t.teamSub}</p></div>${urlLink(official,t.official)}</div><div class="people">${data.team.map(personCard).join('')}</div><p class="people-source">${t.peopleSource}</p></section>
${blogs.length?`<section class="section" id="blog"><h2>${t.blog}</h2><p class="sub">${t.blogSub}</p><div class="reading-grid">${blogs.map(entryCard).join('')}</div></section>`:''}
<section class="section contact"><div><h2>${t.contact}</h2><p>${t.contactBody}</p></div><a class="contact-link" href="mailto:nuria.aquilue@ctfc.cat">nuria.aquilue@ctfc.cat</a></section>
${siteFooter()}</main>`;
const current=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Madrid',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),events=data.entries.filter(e=>e.type==='activity'),upcoming=events.filter(e=>e.date>=current).sort((a,b)=>a.date.localeCompare(b.date)),past=events.filter(e=>e.date<current).sort(order);document.getElementById('events').innerHTML=(upcoming.map(entryCard).join('')||`<p class="empty-state">${t.upcomingEmpty}</p>`)+(past.length?`<details open><summary>${t.past}</summary>${past.map(entryCard).join('')}</details>`:'');renderNews();finishLayout();}

let publicationYear='all',publicationKind='all',publicationSearch='';
const catalogueCopy={en:{intro:'Research outputs involving current LANDMOD members, 2024–2026. Articles, chapters, conference contributions, preprints and research resources are identified separately. Earlier selected work is retained below.',search:'Search title, author or DOI',year:'Year',kind:'Type',all:'All',count:'results',audit:'Sources and coverage',types:{article:'Articles',chapter:'Chapters',conference:'Conferences',preprint:'Preprints',dataset:'Data',software:'Software',report:'Reports',other:'Other outputs'}},es:{intro:'Resultados de investigación con participación de miembros actuales de LANDMOD, 2024–2026. Se distinguen artículos, capítulos, congresos, preprints y recursos de investigación. Se conservan también los trabajos anteriores destacados.',search:'Buscar título, autor o DOI',year:'Año',kind:'Tipo',all:'Todo',count:'resultados',audit:'Fuentes y cobertura',types:{article:'Artículos',chapter:'Capítulos',conference:'Congresos',preprint:'Preprints',dataset:'Datos',software:'Software',report:'Informes',other:'Otros resultados'}},ca:{intro:'Resultats de recerca amb participació de membres actuals de LANDMOD, 2024–2026. Es distingeixen articles, capítols, congressos, preprints i recursos de recerca. També es conserven els treballs anteriors destacats.',search:'Cercar títol, autor o DOI',year:'Any',kind:'Tipus',all:'Tot',count:'resultats',audit:'Fonts i cobertura',types:{article:'Articles',chapter:'Capítols',conference:'Congressos',preprint:'Preprints',dataset:'Dades',software:'Software',report:'Informes',other:'Altres resultats'}}};
function renderPublicationCatalogue(){const section=document.getElementById('publicaciones');if(!section)return;const t=catalogueCopy[lang];document.title=dictionaries[lang].papers+' · LANDMOD';section.innerHTML=`<h1>${dictionaries[lang].papers}</h1><p class="sub">${t.intro}</p><div class="publication-controls"><label>${t.search}<input id="publication-search" type="search" value="${esc(publicationSearch)}"></label><label>${t.year}<select id="publication-year"><option value="all">${t.all}</option>${['2026','2025','2024','2023'].map(y=>`<option value="${y}" ${publicationYear===y?'selected':''}>${y}</option>`).join('')}</select></label><label>${t.kind}<select id="publication-kind"><option value="all">${t.all}</option>${Object.entries(t.types).map(([key,label])=>`<option value="${key}" ${publicationKind===key?'selected':''}>${label}</option>`).join('')}</select></label></div><p class="sub"><a href="/uploads/publications/coverage.html?lang=${lang}">${t.audit}</a> · <a href="/uploads/publications/landmod-2024-2026.bib" download>BibTeX</a></p><p id="publication-count" class="sub" role="status"></p><div id="publication-results"></div>`;updatePublicationResults();}
function updatePublicationResults(){const target=document.getElementById('publication-results');if(!target)return;const t=catalogueCopy[lang],query=publicationSearch.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const items=data.entries.filter(e=>e.type==='paper'&&(publicationYear==='all'||e.date.startsWith(publicationYear))&&(publicationKind==='all'||(e.publication_kind||'article')===publicationKind)&&[textFor(e,'title'),e.authors,e.doi,(e.team_members||[]).join(' ')].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(query)).sort(order);document.getElementById('publication-count').textContent=items.length+' '+(items.length===1?({en:'result',es:'resultado',ca:'resultat'}[lang]):t.count);const years=[...new Set(items.map(e=>e.date.slice(0,4)))].sort((a,b)=>b.localeCompare(a));target.innerHTML=years.map(year=>`<section class="publication-year"><h2>${year}</h2>${items.filter(e=>e.date.startsWith(year)).map(e=>`<article class="publication-record"><p class="news-meta"><time datetime="${e.date.slice(0,e.date_precision==='year'?4:7)}">${publicationDate(e)}</time><span aria-hidden="true"> · </span><span>${esc(t.types[e.publication_kind||'article']||t.types.other)}</span></p><h3>${urlLink(e.doi?'https://doi.org/'+e.doi:e.url,esc(textFor(e,'title')))}</h3>${reference(e)}${e.team_members?.length?`<p class="publication-members">LANDMOD: ${esc(e.team_members.join(' · '))}</p>`:''}<div class="rowlinks">${e.doi?urlLink('https://doi.org/'+e.doi,'DOI: '+esc(e.doi)):''}</div></article>`).join('')}</section>`).join('');}
document.addEventListener('input',e=>{if(e.target.id==='publication-search'){publicationSearch=e.target.value;updatePublicationResults();}});
document.addEventListener('change',e=>{if(e.target.id==='publication-year')publicationYear=e.target.value;else if(e.target.id==='publication-kind')publicationKind=e.target.value;else return;updatePublicationResults();});

function projectLogo(p){if(!p.logo)return `<span class="project-wordmark">${esc(p.name)}</span>`;const size=p.logo_size||[240,90],box=p.logo_viewbox||[0,0,...size];return `<svg class="project-logo-art" viewBox="${box.join(' ')}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${esc(p.name)}"><image href="${esc(p.logo)}" x="0" y="0" width="${size[0]}" height="${size[1]}"/></svg>`;}
const projectId=p=>p.name.toLowerCase().replace(/[^a-z0-9]+/g,'-');
const projectCopy={en:{title:'Projects',intro:'Research projects and collaborations connecting landscape modelling, forest management and biodiversity conservation.',website:'Official project website',note:'This selection includes ongoing and completed collaborations. Visit each project website for its partners, dates and results.'},es:{title:'Proyectos',intro:'Proyectos y colaboraciones que conectan la modelización del paisaje, la gestión forestal y la conservación de la biodiversidad.',website:'Web oficial del proyecto',note:'Esta selección incluye colaboraciones en curso y finalizadas. Consulta las webs oficiales para conocer sus socios, fechas y resultados.'},ca:{title:'Projectes',intro:'Projectes i col·laboracions que connecten la modelització del paisatge, la gestió forestal i la conservació de la biodiversitat.',website:'Web oficial del projecte',note:'Aquesta selecció inclou col·laboracions en curs i finalitzades. Consulta les webs oficials per conèixer-ne els socis, les dates i els resultats.'}};
function projectFacts(p){
 const c={en:{period:'Period',budget:'Total project budget',grant:'Total grant',pending:'To be confirmed',source:'Dates and funding source'},es:{period:'Periodo',budget:'Presupuesto total del proyecto',grant:'Subvención total',pending:'Por confirmar',source:'Fuente de fechas y financiación'},ca:{period:'Període',budget:'Pressupost total del projecte',grant:'Subvenció total',pending:'Per confirmar',source:'Font de dates i finançament'}}[lang];
 const date=v=>!v?'':v.length===4?v:new Intl.DateTimeFormat(lang,{month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(v.length===7?v+'-01':v));
 const period=p.start_date&&p.end_date?date(p.start_date)+' – '+date(p.end_date):c.pending;
 const amount=typeof p.budget_eur==='number'?new Intl.NumberFormat(lang,{style:'currency',currency:'EUR',minimumFractionDigits:2,maximumFractionDigits:2}).format(p.budget_eur):c.pending;
 return `<dl class="project-facts"><div><dt>${c.period}</dt><dd>${esc(period)}</dd></div><div><dt>${p.budget_basis==='grant'?c.grant:c.budget}</dt><dd>${esc(amount)}</dd></div></dl>`;
}
function projectsPage(){const c=projectCopy[lang];return `<section class="projects-page"><a class="breadcrumb" href="${homeURL()}">${lang==='en'?'Back to home':lang==='es'?'Volver al inicio':'Tornar a l’inici'}</a><h1>${c.title}</h1><p class="page-intro">${c.intro}</p><div class="projects-catalogue">${data.projects.filter(p=>p.kind==='project').map(p=>`<article class="project-detail" id="${projectId(p)}"><div class="project-logo ${p.logo_theme==='dark'?'project-logo-dark':''}">${projectLogo(p)}</div><div><h2>${esc(p.name)}</h2>${projectFacts(p)}<p>${esc(p['description_'+lang]||p['label_'+lang]||p.label_en)}</p>${urlLink(p.url,c.website)}</div></article>`).join('')}</div><p class="source-note">${c.note}</p></section>`;}

function finishLayout(){
 const main=document.querySelector('main');const footer=main.querySelector('footer').outerHTML;
 if(location.pathname.endsWith('/section.html')){
  if(isNewsArchive()){const news=document.getElementById('noticias');news.querySelector('.news-archive-link')?.remove();news.querySelector('.section-head>a')?.remove();news.classList.add('latest-news');const title=news.querySelector('h2');const h=document.createElement('h1');h.textContent=({en:'All news',es:'Todas las noticias',ca:'Totes les notícies'}[lang]);title.replaceWith(h);document.title=h.textContent+' · LANDMOD';main.innerHTML=`<div class="inner-section"><a class="breadcrumb" href="${homeURL()}">${lang==='ca'?'Tornar a l’inici':lang==='es'?'Volver al inicio':'Back to home'}</a>${news.outerHTML}</div>${footer}`;main.classList.add('home-layout');return;}
  if(new URL(location).searchParams.get('view')==='projects'){main.innerHTML=`${projectsPage()}${footer}`;document.title=projectCopy[lang].title+' · LANDMOD';return;}
  const allowed=['publicaciones','equipo'];const view=new URL(location).searchParams.get('view');const section=allowed.includes(view)?document.getElementById(view):null;
  main.innerHTML=`<div class="inner-section"><a class="breadcrumb" href="${homeURL()}">${lang==='ca'?"Tornar a les notícies":lang==='es'?'Volver a las noticias':'Back to latest news'}</a>${section?section.outerHTML:`<h1>${lang==='ca'?"Secció no trobada":lang==='es'?'Sección no encontrada':'Section not found'}</h1>`}</div>${footer}`;
  if(view==='publicaciones'){renderPublicationCatalogue();return;}const heading=main.querySelector('h2');if(heading){const h=document.createElement('h1');h.textContent=heading.textContent;heading.replaceWith(h);document.title=h.textContent+' · LANDMOD';}return;
 }
 const news=document.getElementById('noticias');
 for(const child of [...main.children])if(child!==news&&child.tagName!=='FOOTER')child.remove();
 const copy={en:{heading:'Modelling landscapes.<br><em>Informing decisions.</em>',description:'Models and data to explore forest management, restoration and more resilient landscapes.',research:'Our research',team:'Meet the team',image:'Agroforestry landscape with fields and woodland',credit:'CTFC · Resilient landscapes'},es:{heading:'Modelizar paisajes.<br><em>Orientar decisiones.</em>',description:'Modelos y datos para explorar la gestión forestal, la restauración y unos paisajes más resilientes.',research:'Nuestra investigación',team:'Conoce al equipo',image:'Paisaje agroforestal con cultivos y bosques',credit:'CTFC · Paisajes resilientes'},ca:{heading:'Modelitzar paisatges.<br><em>Orientar decisions.</em>',description:'Models i dades per explorar la gestió forestal, la restauració i uns paisatges més resilients.',research:'La nostra recerca',team:'Coneix l’equip',image:'Paisatge agroforestal amb conreus i boscos',credit:'CTFC · Paisatges resilients'}}[lang];
 const mapCopy={en:{label:'From landscapes to decisions',title:'Spatial planning',caption:'Research example · Biomass & solar biorefineries',alt:'Maps of biomass and solar resources in Mediterranean countries'},es:{label:'Del paisaje a las decisiones',title:'Planificación espacial',caption:'Ejemplo de investigación · Biomasa y biorrefinerías solares',alt:'Mapas de biomasa y recursos solares en países mediterráneos'},ca:{label:'Del paisatge a les decisions',title:'Planificació espacial',caption:'Exemple de recerca · Biomassa i biorefineries solars',alt:'Mapes de biomassa i recursos solars en països mediterranis'}}[lang];
 const intro=document.createElement('section');intro.className='home-intro landscape-intro';intro.innerHTML=`<div class="home-intro-copy"><p class="eyebrow">LANDMOD · CTFC</p><h1>${copy.heading}</h1><p class="home-description">${copy.description}</p><div class="home-intro-links"><a href="${sectionURL('investigacion')}">${copy.research} <span aria-hidden="true">↗</span></a><a href="${sectionURL('equipo')}">${copy.team} <span aria-hidden="true">↗</span></a></div></div><div class="landscape-model-composition"><figure class="home-landscape"><img src="/uploads/identity/resilient-landscape.jpg" width="1600" height="416" alt="${copy.image}" fetchpriority="high"><figcaption>${urlLink('https://www.ctfc.cat/l_paisatges.php',copy.credit)}</figcaption></figure></div>`;main.prepend(intro);
 const homeCopy={en:{about:'About LANDMOD',body:'We are the Landscape Modelling group at the Forest Science and Technology Centre of Catalonia (CTFC). We develop and apply models across scales to understand how forests, land use and landscapes change, and to assess management strategies that strengthen their resilience.',topics:['Forest and landscape dynamics','Spatial planning and optimisation','Ecosystem services and restoration'],publications:'Recent publications',projects:'Research projects',projectIntro:'Projects and collaborations connecting our models with forest management and conservation.',more:'All projects'},es:{about:'Sobre LANDMOD',body:'Somos el grupo de Modelización del Paisaje del Centre de Ciència i Tecnologia Forestal de Catalunya (CTFC). Desarrollamos y aplicamos modelos a distintas escalas para entender cómo cambian los bosques, los usos del suelo y los paisajes, y evaluar estrategias de gestión que refuercen su resiliencia.',topics:['Dinámica forestal y del paisaje','Planificación y optimización espacial','Servicios ecosistémicos y restauración'],publications:'Publicaciones recientes',projects:'Proyectos de investigación',projectIntro:'Proyectos y colaboraciones que conectan nuestros modelos con la gestión forestal y la conservación.',more:'Todos los proyectos'},ca:{about:'Sobre LANDMOD',body:'Som el grup de Modelització del Paisatge del Centre de Ciència i Tecnologia Forestal de Catalunya (CTFC). Desenvolupem i apliquem models a diverses escales per entendre com canvien els boscos, els usos del sòl i els paisatges, i avaluar estratègies de gestió que en reforcin la resiliència.',topics:['Dinàmica forestal i del paisatge','Planificació i optimització espacial','Serveis ecosistèmics i restauració'],publications:'Publicacions recents',projects:'Projectes de recerca',projectIntro:'Projectes i col·laboracions que connecten els nostres models amb la gestió forestal i la conservació.',more:'Tots els projectes'}}[lang];
 const about=document.createElement('section');about.className='home-about';about.id='about';about.setAttribute('aria-labelledby','home-about-title');about.innerHTML=`<h2 id="home-about-title">${homeCopy.about}</h2><div><p>${homeCopy.body}</p><ul class="research-topics">${dictionaries[lang].researchAreas.map(([title,body])=>`<li><h3>${title}</h3><p>${body}</p></li>`).join('')}</ul></div>`;intro.after(about);
 const publications=document.createElement('section');publications.className='home-publications';publications.id='recent-publications';
 const recent=data.entries.filter(e=>e.type==='paper'&&(e.publication_kind||'article')==='article').sort(order).slice(0,3);
 publications.innerHTML=`<div class="section-head"><h2>${homeCopy.publications}</h2><a href="${sectionURL('publicaciones')}">${dictionaries[lang].allPapers}</a></div><div class="recent-publications-list">${recent.map(e=>`<article class="recent-publication"><time datetime="${e.date.slice(0,7)}">${publicationDate(e)}</time><div><h3>${urlLink(e.doi?'https://doi.org/'+e.doi:e.url,esc(textFor(e,'title')))}</h3><p>${esc(e.venue||'')}</p></div></article>`).join('')}</div>`;news.after(publications);
 const projects=document.createElement('section');projects.className='home-projects';projects.id='projects';projects.innerHTML=`<div class="section-head"><div><h2>${homeCopy.projects}</h2><p>${homeCopy.projectIntro}</p></div><a href="${sectionURL('projects')}">${homeCopy.more}</a></div><div class="home-project-grid">${data.projects.filter(p=>p.kind==='project'&&p.featured).slice(0,4).map(p=>`<a class="home-project" href="${sectionURL('projects')}#${projectId(p)}"><div class="project-logo ${p.logo_theme==='dark'?'project-logo-dark':''}">${projectLogo(p)}</div><h3>${esc(p.name)}</h3><p>${esc(p['label_'+lang]||p.label_en)}</p></a>`).join('')}</div>`;publications.after(projects);
 // The hero provides the page heading; Latest news remains a section heading.
 news.querySelector('.section-head p')?.remove();news.querySelector('.section-head>a')?.remove();news.querySelector('.filters')?.remove();news.classList.add('latest-news');main.classList.add('home-layout');
}
function renderEntryPage(id){
 render();const entry=data.entries.find(e=>e.id===id),t=dictionaries[lang];const main=document.querySelector('main');
 if(!entry){main.innerHTML=`<section class="note-page"><h1>${lang==='ca'?"No hem trobat aquesta nota":lang==='es'?'No encontramos esta nota':'Entry not found'}</h1><a href="${homeURL()}#noticias">${lang==='ca'?"Tornar a l’actualitat":lang==='es'?'Volver a la actualidad':'Back to news'}</a></section>`;return;}
 document.title=textFor(entry,'title')+' · LANDMOD';document.querySelector('meta[name="description"]').content=summaryFor(entry);
 main.innerHTML=`<article class="note-page"><a class="breadcrumb" href="${sectionURL(entry.type==='paper'?'publicaciones':'noticias')}">${lang==='ca'?"Tornar a LANDMOD":lang==='es'?'Volver a LANDMOD':'Back to LANDMOD'}</a><p class="eyebrow">${t.types[entry.type]} · ${dateFor(entry)}</p><h1>${esc(textFor(entry,'title'))}</h1>${reference(entry,true)}<div class="note-content">${!entry.title[lang]||!entry.body[lang]?`<p class="notice">${t.translation}</p>`:''}${imageFor(entry)}${DOMPurify.sanitize(marked.parse(textFor(entry,'body')))}</div>${links(entry)}${safeURL(entry.thumbnail_source)?`<p class="thumbnail-credit">${lang==='ca'?"Miniatura:":lang==='es'?'Miniatura:':'Thumbnail:'} ${urlLink(entry.thumbnail_source,esc(textFor(entry,'thumbnail_credit')||'CTFC'))}</p>`:''}${safeURL(entry.source)?`<div class="source-note">${urlLink(entry.source,t.source)}</div>`:''}<div class="note-bottom"><button class="textbutton" id="copy-link">${t.copy}</button><span id="copy-status" role="status"></span><a href="${homeURL()}#noticias">${lang==='ca'?"Més notícies":lang==='es'?'Más noticias':'More news'}</a></div></article>${siteFooter()}`;
}
function renderSoftwarePage(){
 render();const es=lang==='es';document.title='Software · LANDMOD · CTFC';document.querySelector('main').innerHTML=`<section class="software-page"><a class="breadcrumb" href="${homeURL()}">${lang==='ca'?"Tornar a LANDMOD":es?'Volver a LANDMOD':'Back to LANDMOD'}</a><p class="eyebrow">${lang==='ca'?"Modelització i planificació":es?'Modelización y planificación':'Modelling and planning'}</p><h1>Software <em>${lang==='ca'?"i eines":es?'y herramientas':'and tools'}</em></h1><p class="page-intro">${lang==='ca'?"Codi, documentació i plataformes per passar de les preguntes als models. Cada fitxa reconeix els seus autors i les institucions que col·laboren en el seu desenvolupament.":es?'Código, documentación y plataformas para pasar de las preguntas a los modelos. Cada ficha reconoce a sus autores y las instituciones que colaboran en su desarrollo.':'Code, documentation and platforms to turn questions into models. Each entry credits its authors and collaborating institutions.'}</p><div class="filters" role="group" aria-label="${lang==='ca'?"Filtrar software":es?'Filtrar software':'Filter software'}">${[['all',lang==='ca'?"Tot":es?'Todo':'All'],['r',lang==='ca'?"Paquets R":es?'Paquetes R':'R packages'],['web',lang==='ca'?"Aplicacions web":es?'Aplicaciones web':'Web applications']].map(([key,label])=>`<button data-software-filter="${key}" aria-pressed="${key===softwareFilter}">${label}</button>`).join('')}</div><div class="software-list">${(data.software||[]).filter(tool=>softwareFilter==='all'||tool.kind===softwareFilter).map(tool=>`<article class="software-item" id="${esc(tool.id)}"><div class="tool-symbol">${tool.kind==='r'?'R':'WEB'}</div><div><p class="eyebrow">${tool.kind==='r'?(lang==='ca'?"Paquet R":es?'Paquete R':'R package'):(lang==='ca'?"Aplicació web":es?'Aplicación web':'Web application')}</p><h2>${esc(tool.name)}</h2><p>${esc(tool['description_'+lang])}</p><p class="tool-credit">${esc(tool['credit_'+lang])}</p><div class="rowlinks">${tool.documentation?urlLink(tool.documentation,lang==='ca'?"Documentació":es?'Documentación':'Documentation'):''}${tool.repository?urlLink(tool.repository,lang==='ca'?"Codi font":es?'Código fuente':'Source code'):''}${urlLink(tool.url,lang==='ca'?"Web de l’eina":es?'Sitio de la herramienta':'Tool website')}${tool.source!==tool.url?urlLink(tool.source,lang==='ca'?"Autoria i context":es?'Autoría y contexto':'Authorship and context'):''}</div></div></article>`).join('')}</div><p class="sub" aria-live="polite">${lang==='ca'?"Les versions i les instruccions d’instal·lació es mantenen a la documentació oficial de cada eina.":es?'Las versiones y las instrucciones de instalación se mantienen en la documentación oficial de cada herramienta.':'Versions and installation instructions are maintained in each tool’s official documentation.'}</p><p class="source-note">${lang==='ca'?"Consulta també el catàleg del nostre grup col·lega":es?'Conoce también el catálogo de nuestro grupo colega':'Explore our colleagues’ catalogue at'} ${urlLink('https://emf.creaf.cat/software/','Ecosystem Modelling Facility · CREAF')}.</p></section>${siteFooter()}`;
}
function markCurrentNavigation(){const view=new URLSearchParams(location.search).get('view');const current=location.pathname.endsWith('/software.html')?'software':location.pathname.endsWith('/section.html')?(view||'noticias'):'noticias';document.querySelectorAll('header nav a').forEach(a=>{const url=new URL(a.href);const target=url.pathname.endsWith('/software.html')?'software':url.searchParams.get('view')||'noticias';if(target===current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function renderCurrentPage(){const id=new URL(location).searchParams.get('id');if(location.pathname.endsWith('/entry.html'))renderEntryPage(id);else if(location.pathname.endsWith('/software.html'))renderSoftwarePage();else render();markCurrentNavigation();}
document.addEventListener('click',async e=>{const language=e.target.closest('[data-lang]');if(language){const id=new URL(location).searchParams.get('entry');lang=language.dataset.lang;const url=new URL(location);url.searchParams.set('lang',lang);history.replaceState(null,'',url);renderCurrentPage();return;}const sf=e.target.closest('[data-software-filter]');if(sf){softwareFilter=sf.dataset.softwareFilter;renderSoftwarePage();return;}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;const u=new URL(location);if(filter==='all')u.searchParams.delete('filter');else u.searchParams.set('filter',filter);history.replaceState(null,'',u);expanded=false;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===f)));renderNews();return;}if(e.target.closest('#expand')){expanded=!expanded;renderNews();return;}if(e.target.closest('#copy-link')){try{await navigator.clipboard.writeText(location.href);document.getElementById('copy-status').textContent=dictionaries[lang].copied;}catch{document.getElementById('copy-status').textContent=location.href;}return;}});
async function start(){const oldView=new URL(location).searchParams.get('view');if(location.pathname.endsWith('/section.html')&&['investigacion','blog','actividades'].includes(oldView)){location.replace(oldView==='investigacion'?sectionURL('investigacion'):sectionURL('noticias')+'&filter='+(oldView==='blog'?'blog':'activity'));return;}const response=await fetch('content.json',{cache:'no-store'});if(!response.ok)throw Error('content.json');data=await response.json();const legacy=new URL(location).searchParams.get('entry');if(legacy){location.replace(entryURL({id:legacy}));return;}renderCurrentPage();if(location.hash){const target=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(target)target.scrollIntoView({behavior:'instant'});}}
start().catch(()=>{document.getElementById('app').innerHTML=`<main><p>${dictionaries[lang].loadError}</p></main>`;});
